INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-quad-sets', NULL, 'Quad sets', 'Knee', 'Strengthening', 'Sit or lie with your leg straight. Tighten the muscle on top of your thigh, pressing the back of your knee into the floor. Hold, then relax.', 'https://www.youtube.com/results?search_query=Quad%20sets%20physical%20therapy%20exercise', '3x10, hold 5s');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-straight-leg-raise', NULL, 'Straight leg raise', 'Knee', 'Strengthening', 'Lie on your back, other knee bent. Tighten your thigh and lift the straight leg to the height of the bent knee. Lower slowly.', 'https://www.youtube.com/results?search_query=Straight%20leg%20raise%20physical%20therapy%20exercise', '3x10');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-heel-slides', NULL, 'Heel slides', 'Knee', 'Mobility', 'Lie on your back. Slowly slide your heel toward your buttocks, bending the knee as far as comfortable, then slide back.', 'https://www.youtube.com/results?search_query=Heel%20slides%20physical%20therapy%20exercise', '2x15');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-short-arc-quads', NULL, 'Short arc quads', 'Knee', 'Strengthening', 'Lie with a towel roll under your knee. Straighten the knee fully, lifting the heel, hold, then lower.', 'https://www.youtube.com/results?search_query=Short%20arc%20quads%20physical%20therapy%20exercise', '3x10, hold 3s');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-mini-squat', NULL, 'Mini squat', 'Knee', 'Strengthening', 'Stand holding a counter. Bend your knees slightly as if sitting back, keeping knees over toes. Return to standing.', 'https://www.youtube.com/results?search_query=Mini%20squat%20physical%20therapy%20exercise', '3x10');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-step-ups', NULL, 'Step-ups', 'Knee', 'Strengthening', 'Step up onto a low step with one leg, bring the other up, then step down leading with the same leg. Control the movement.', 'https://www.youtube.com/results?search_query=Step-ups%20physical%20therapy%20exercise', '3x10');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-terminal-knee-extension', NULL, 'Terminal knee extension', 'Knee', 'Strengthening', 'Loop a band behind your knee anchored in front. From a slightly bent knee, straighten fully against the band, then release.', 'https://www.youtube.com/results?search_query=Terminal%20knee%20extension%20physical%20therapy%20exercise', '3x15');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-clamshells', NULL, 'Clamshells', 'Hip', 'Strengthening', 'Lie on your side, knees bent, feet together. Lift the top knee without rolling your pelvis back. Lower slowly.', 'https://www.youtube.com/results?search_query=Clamshells%20physical%20therapy%20exercise', '3x12');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-glute-bridge', NULL, 'Glute bridge', 'Hip', 'Strengthening', 'Lie on your back, knees bent. Squeeze your glutes and lift your hips until body forms a straight line. Hold, then lower.', 'https://www.youtube.com/results?search_query=Glute%20bridge%20physical%20therapy%20exercise', '3x10, hold 3s');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-side-lying-hip-abduction', NULL, 'Side-lying hip abduction', 'Hip', 'Strengthening', 'Lie on your side, bottom knee bent. Keep the top leg straight and slightly behind you, lift it toward the ceiling, then lower.', 'https://www.youtube.com/results?search_query=Side-lying%20hip%20abduction%20physical%20therapy%20exercise', '3x10');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-hip-flexor-stretch', NULL, 'Hip flexor stretch', 'Hip', 'Stretching', 'Kneel on one knee, other foot in front. Tuck your pelvis and shift forward until you feel a stretch at the front of the kneeling hip.', 'https://www.youtube.com/results?search_query=Hip%20flexor%20stretch%20physical%20therapy%20exercise', '3x :30 seconds');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-hamstring-stretch', NULL, 'Hamstring stretch', 'Hip', 'Stretching', 'Lie on your back and loop a strap around one foot. Keep the knee straight and raise the leg until you feel a stretch behind the thigh.', 'https://www.youtube.com/results?search_query=Hamstring%20stretch%20physical%20therapy%20exercise', '3x :30 seconds');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-piriformis-stretch', NULL, 'Piriformis stretch', 'Hip', 'Stretching', 'Lie on your back, cross one ankle over the other knee, and pull the bottom thigh toward your chest until you feel a stretch in the buttock.', 'https://www.youtube.com/results?search_query=Piriformis%20stretch%20physical%20therapy%20exercise', '3x :30 seconds');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-pelvic-tilt', NULL, 'Pelvic tilt', 'Low back', 'Mobility', 'Lie on your back with knees bent. Flatten your low back into the floor by tightening your abs, hold, then relax.', 'https://www.youtube.com/results?search_query=Pelvic%20tilt%20physical%20therapy%20exercise', '2x10, hold 5s');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-cat-cow', NULL, 'Cat-cow', 'Low back', 'Mobility', 'On hands and knees, slowly round your back toward the ceiling, then let it sag while lifting your head. Move within comfort.', 'https://www.youtube.com/results?search_query=Cat-cow%20physical%20therapy%20exercise', '2x10');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-bird-dog', NULL, 'Bird dog', 'Low back', 'Stability', 'On hands and knees, extend one arm and the opposite leg while keeping your trunk still. Hold, return, switch sides.', 'https://www.youtube.com/results?search_query=Bird%20dog%20physical%20therapy%20exercise', '3x8, hold 5s');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-dead-bug', NULL, 'Dead bug', 'Core', 'Stability', 'Lie on your back, arms up, hips and knees at 90 degrees. Slowly lower opposite arm and leg while keeping your back flat.', 'https://www.youtube.com/results?search_query=Dead%20bug%20physical%20therapy%20exercise', '3x8');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-prone-press-up', NULL, 'Prone press-up', 'Low back', 'Mobility', 'Lie on your stomach, hands under shoulders. Press your upper body up while letting your hips stay on the floor. Lower slowly.', 'https://www.youtube.com/results?search_query=Prone%20press-up%20physical%20therapy%20exercise', '2x10, hold 2s');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-front-plank', NULL, 'Front plank', 'Core', 'Stability', 'Support yourself on forearms and toes (or knees) with a straight line from head to heels. Breathe normally.', 'https://www.youtube.com/results?search_query=Front%20plank%20physical%20therapy%20exercise', '3x :20 seconds');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-chin-tucks', NULL, 'Chin tucks', 'Neck', 'Posture', 'Sit tall. Gently draw your chin straight back, making a double chin, without tipping your head. Hold, then relax.', 'https://www.youtube.com/results?search_query=Chin%20tucks%20physical%20therapy%20exercise', '2x10, hold 5s');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-upper-trap-stretch', NULL, 'Upper trap stretch', 'Neck', 'Stretching', 'Sit tall, hold the seat with one hand, and tilt your ear toward the opposite shoulder until you feel a gentle stretch.', 'https://www.youtube.com/results?search_query=Upper%20trap%20stretch%20physical%20therapy%20exercise', '2x :30 seconds');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-scapular-squeeze', NULL, 'Scapular squeeze', 'Shoulder', 'Posture', 'Sit or stand tall. Squeeze your shoulder blades back and down together, hold, then relax.', 'https://www.youtube.com/results?search_query=Scapular%20squeeze%20physical%20therapy%20exercise', '2x10, hold 5s');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-pendulum', NULL, 'Pendulum', 'Shoulder', 'Mobility', 'Lean on a table with your good arm and let the other arm hang. Gently swing it in small circles and side to side using body motion.', 'https://www.youtube.com/results?search_query=Pendulum%20physical%20therapy%20exercise', '2x30');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-shoulder-external-rotation-with-band', NULL, 'Shoulder external rotation with band', 'Shoulder', 'Strengthening', 'Elbow at your side bent to 90 degrees, holding a band. Rotate your forearm outward, keeping the elbow tucked. Return slowly.', 'https://www.youtube.com/results?search_query=Shoulder%20external%20rotation%20with%20band%20physical%20therapy%20exercise', '3x12');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-shoulder-internal-rotation-with-band', NULL, 'Shoulder internal rotation with band', 'Shoulder', 'Strengthening', 'Elbow at your side bent to 90 degrees, band anchored to the side. Rotate your forearm across your body, then return slowly.', 'https://www.youtube.com/results?search_query=Shoulder%20internal%20rotation%20with%20band%20physical%20therapy%20exercise', '3x12');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-band-rows', NULL, 'Band rows', 'Shoulder', 'Strengthening', 'Hold a band anchored in front at chest height. Pull elbows back, squeezing shoulder blades together, then return slowly.', 'https://www.youtube.com/results?search_query=Band%20rows%20physical%20therapy%20exercise', '3x12');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-wall-slides', NULL, 'Wall slides', 'Shoulder', 'Mobility', 'Stand with your back and forearms against a wall. Slide your arms up the wall as far as comfortable, then back down.', 'https://www.youtube.com/results?search_query=Wall%20slides%20physical%20therapy%20exercise', '2x10');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-ankle-pumps', NULL, 'Ankle pumps', 'Ankle', 'Mobility', 'Lying or sitting, point your toes away and then pull them toward you, moving through full range.', 'https://www.youtube.com/results?search_query=Ankle%20pumps%20physical%20therapy%20exercise', '2x20');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-ankle-alphabet', NULL, 'Ankle alphabet', 'Ankle', 'Mobility', 'Sitting with your foot off the floor, trace the letters of the alphabet with your big toe.', 'https://www.youtube.com/results?search_query=Ankle%20alphabet%20physical%20therapy%20exercise', '1x1');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-calf-raises', NULL, 'Calf raises', 'Ankle', 'Strengthening', 'Stand holding a counter. Rise up onto your toes, pause, and lower slowly.', 'https://www.youtube.com/results?search_query=Calf%20raises%20physical%20therapy%20exercise', '3x15');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-calf-stretch', NULL, 'Calf stretch', 'Ankle', 'Stretching', 'Stand facing a wall with one leg back, heel down and knee straight. Lean forward until you feel a stretch in the calf.', 'https://www.youtube.com/results?search_query=Calf%20stretch%20physical%20therapy%20exercise', '3x :30 seconds');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-single-leg-balance', NULL, 'Single-leg balance', 'Balance', 'Balance', 'Stand on one leg near a counter for support. Keep a soft knee and stay steady. Progress by closing your eyes or standing on a pillow.', 'https://www.youtube.com/results?search_query=Single-leg%20balance%20physical%20therapy%20exercise', '3x :30 seconds');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-wrist-flexor-stretch', NULL, 'Wrist flexor stretch', 'Wrist', 'Stretching', 'Arm straight in front, palm up. With the other hand, gently pull your fingers back toward you until you feel a stretch.', 'https://www.youtube.com/results?search_query=Wrist%20flexor%20stretch%20physical%20therapy%20exercise', '2x :30 seconds');
INSERT INTO exercises (id, therapist_id, name, body_area, category, description, video_url, default_instructions) VALUES ('builtin-thoracic-extension-over-chair', NULL, 'Thoracic extension over chair', 'Upper back', 'Mobility', 'Sit in a chair with a low back. Hands behind head, gently arch your upper back over the top of the chair, then return.', 'https://www.youtube.com/results?search_query=Thoracic%20extension%20over%20chair%20physical%20therapy%20exercise', '2x10');
